import { enhancePrompt, completionModel } from "@/lib/server/enhance";
import { ImageApiError } from "@/lib/server/openai";

export const maxDuration = 120;

const MAX_VARIATIONS = 12;

/** POST { prompt, count } → { model, prompts: [{ title, prompt }] } generated by OPENAI_COMPLETION_MODEL. */
export async function POST(request: Request) {
  const body = (await request.json().catch(() => null)) as { prompt?: string; count?: number } | null;
  const idea = body?.prompt?.trim();
  if (!idea) return Response.json({ error: "Write an idea to enhance first." }, { status: 400 });
  if (idea.length > 2000) return Response.json({ error: "Keep the idea under 2000 characters." }, { status: 400 });
  const count = Math.min(MAX_VARIATIONS, Math.max(1, Math.floor(body?.count ?? 6)));

  try {
    const prompts = await enhancePrompt(idea, count, request.signal);
    return Response.json({ model: completionModel(), prompts });
  } catch (err) {
    const status = err instanceof ImageApiError ? err.status : 500;
    const message = err instanceof Error ? err.message : "Prompt enhancement failed.";
    return Response.json({ error: message }, { status: status >= 400 && status < 600 ? status : 500 });
  }
}
